#!/usr/bin/env python3
"""Payroll summary from time clock exports. Usage: payroll.py INPUT_DIR OUTPUT_FILE"""
import csv
import gzip
import io
import json
import os
import sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data.decode("utf-8-sig")


def lines_of(text):
    return [l for l in text.splitlines() if l.strip()]


def to_ts(dt):
    return int((dt - EPOCH).total_seconds())


def local_to_ts(naive, zone, fold=0):
    return to_ts(naive.replace(tzinfo=zone, fold=fold))


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


def iso_ts(s):
    dt = parse_iso(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return to_ts(dt)


def norm_dir(s):
    s = s.strip().upper()
    if s in ("IN", "I", "K", "CLOCK_IN"):
        return "IN"
    if s in ("OUT", "O", "G", "CLOCK_OUT"):
        return "OUT"
    return None


# ---------------------------------------------------------------- parsers
# each yields (punch_id, employee, direction, ts)

def parse_abbr_csv(text, zone):
    header = None
    for line in lines_of(text):
        row = next(csv.reader([line]))
        cells = [c.strip() for c in row]
        if "Badge" in cells and "Punch" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].upper().strip()
        ampm = None
        if t.endswith("AM") or t.endswith("PM"):
            ampm = t[-2:]
            t = t[:-2].strip()
        h, m, s = (int(x) for x in t.split(":"))
        if ampm:
            h = h % 12 + (12 if ampm == "PM" else 0)
        naive = d.replace(hour=h, minute=m, second=s)
        ab = r.get("Zone", "").strip().upper()
        fold = 1 if ab.endswith("ST") else 0
        yield r["Record"], r["Badge"], norm_dir(r["Punch"]), local_to_ts(naive, zone, fold)


def parse_epoch_jsonl(text, zone):
    schema = 1
    for line in lines_of(text):
        o = json.loads(line)
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = int(o["schema"])
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            pid, emp, dr = o.get("punch_id"), o.get("employee"), o.get("direction")
            ts = int(o["epoch_ms"]) // 1000
        else:
            pid, emp, dr = o.get("id"), o.get("emp"), o.get("dir")
            if "ts" in o:
                ts = int(o["ts"])
            else:
                ts = int(o["ts_ms"]) // 1000
        if pid is None or emp is None:
            continue
        yield str(pid), str(emp), norm_dir(dr), ts


def parse_offset_csv(text, zone):
    rdr = csv.DictReader(io.StringIO(text), delimiter=";")
    for r in rdr:
        r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
        if not r.get("punch_id") or r["punch_id"] == "punch_id":
            continue
        yield r["punch_id"], r["employee"], norm_dir(r["event"]), iso_ts(r["timestamp"])


def parse_legacy(text, zone):
    off = None
    for line in text.splitlines():
        if not line.strip():
            continue
        t = line[0]
        if t == "H":
            f = line[13:18].strip()
            if len(f) == 5 and f[0] in "+-":
                sec = (int(f[1:3]) * 60 + int(f[3:5])) * 60
                off = sec if f[0] == "+" else -sec
            else:
                off = None
        elif t == "D":
            line = line.rstrip("\r\n")
            pid = line[1:9]
            badge = line[9:15].strip()
            dr = norm_dir(line[15])
            dt = datetime.strptime(line[16:30], "%Y%m%d%H%M%S")
            if off is None:
                z = dt.replace(tzinfo=zone)
                o = int((z.utcoffset() - z.dst()).total_seconds())
            else:
                o = off
            ts = to_ts(dt.replace(tzinfo=UTC)) - o
            yield pid, "E" + badge, dr, ts


def parse_de_tsv(text, zone):
    header = None
    for line in lines_of(text):
        cells = [c.strip() for c in line.split("\t")]
        if "Ausweis" in cells:
            header = cells
            continue
        if header is None:
            continue
        r = dict(zip(header, cells))
        d, mo, y = (int(x) for x in r["Datum"].split("."))
        hh, mm = (int(x) for x in r["Uhrzeit"].split(":")[:2])
        naive = datetime(y, mo, d, hh, mm)
        fold = 0 if r.get("Zeitzone", "").upper() == "MESZ" else 1
        yield r["Nr"], r["Ausweis"], norm_dir(r["Buchung"]), local_to_ts(naive, zone, fold)


def parse_local_csv(text, zone):
    for r in csv.DictReader(io.StringIO(text)):
        r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
        naive = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
        yield r["punch_ref"], r["employee_id"], norm_dir(r["direction"]), local_to_ts(naive, zone, 0)


def parse_local_jsonl(text, zone):
    for line in lines_of(text):
        o = json.loads(line)
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p["at"], "%Y-%m-%d %H:%M:%S")
        yield str(p["id"]), str(p["badge"]), norm_dir(p["type"]), local_to_ts(naive, zone, 0)


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


def walk_files(d):
    out = []
    for root, _, files in os.walk(d):
        for f in files:
            out.append(os.path.join(root, f))
    return sorted(out)


def read_csv_rows(path):
    return list(csv.DictReader(io.StringIO(read_text(path))))


def round_ts(ts, zone):
    off = int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
    local = ts + off
    return ((local + 180) // 360) * 360 - off


def local_date(ts, zone):
    return datetime.fromtimestamp(ts, UTC).astimezone(zone).date()


def night_minutes(tin, tout, zone):
    d0 = local_date(tin, zone) - timedelta(days=1)
    d1 = local_date(tout, zone) + timedelta(days=1)
    total = 0
    d = d0
    while d <= d1:
        a = local_to_ts(datetime(d.year, d.month, d.day, 22), zone)
        n = d + timedelta(days=1)
        b = local_to_ts(datetime(n.year, n.month, n.day, 6), zone)
        lo, hi = max(a, tin), min(b, tout)
        if hi > lo:
            total += (hi - lo) // 60
        d += timedelta(days=1)
    return total


def round_cents(fr):
    return (fr * 100 + Fraction(1, 2)).__floor__()


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    period = json.loads(read_text(os.path.join(indir, "period.json")))
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = iso_ts(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_rows(os.path.join(indir, "sites.csv")):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())
    employees = {}
    for r in read_csv_rows(os.path.join(indir, "employees.csv")):
        employees[r["employee_id"].strip()] = r["home_site"].strip()
    rates = {}
    for r in read_csv_rows(os.path.join(indir, "rates.csv")):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Fraction(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}   # (site, id) -> [emp, dir, ts]
    existed = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(indir, "exports", site)
        if not os.path.isdir(d):
            continue
        for path in walk_files(d):
            text = read_text(path)
            for pid, emp, dr, ts in PARSERS[fmt](text, zone):
                key = (site, pid)
                if key in punches or dr is None:
                    continue
                punches[key] = [emp.strip(), dr, ts]
                existed.add(key)

    # 2. corrections
    corr = []
    cdir = os.path.join(indir, "corrections")
    if os.path.isdir(cdir):
        for path in walk_files(cdir):
            for r in read_csv_rows(path):
                r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                if not r.get("correction_id") or r["correction_id"] == "correction_id":
                    continue
                corr.append((iso_ts(r["issued_at"]), r["correction_id"], r))
    corr.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for issued, _, r in corr:
        if issued > cutoff:
            continue
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = iso_ts(r["time"])
                applied += 1
        elif act == "add":
            dr = norm_dir(r["type"])
            if key not in existed and r["site"] in sites and dr:
                punches[key] = [r["employee"], dr, iso_ts(r["time"])]
                existed.add(key)
                applied += 1

    by_emp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            by_emp.setdefault(emp, []).append((ts, 0 if dr == "OUT" else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0))
           for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    for emp, plist in by_emp.items():
        hz = sites[employees[emp]][0]
        plist.sort(key=lambda p: p[:4])
        kept = []
        last = None
        for ts, _, site, pid, dr in plist:
            zone = sites[site][0]
            rts = round_ts(ts, zone)
            wd = local_date(rts, hz)
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                if pstart <= wd <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            last = (ts, dr)
            kept.append((rts, dr, site, wd))

        shifts = []
        pending = None

        def in_period(wd):
            return pstart <= wd <= pend

        for rts, dr, site, wd in kept:
            if dr == "IN":
                if pending is not None and in_period(pending[3]):
                    exc["open_shifts"] += 1
                pending = (rts, dr, site, wd)
            else:
                if pending is not None and rts - pending[0] <= 16 * 3600:
                    shifts.append((pending, (rts, dr, site, wd)))
                    pending = None
                else:
                    if pending is not None and in_period(pending[3]):
                        exc["open_shifts"] += 1
                    pending = None
                    if in_period(wd):
                        exc["orphan_outs"] += 1
        if pending is not None and in_period(pending[3]):
            exc["open_shifts"] += 1

        rows = []
        for i, o in shifts:
            wd = i[3]
            if not in_period(wd):
                continue
            zone = sites[i[2]][0]
            worked = max(0, (o[0] - i[0]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i[0], o[0], zone), paid)
            rows.append([i[0], wd, paid, night, 0, 0])
        rows.sort(key=lambda r: r[0])
        daily = {}
        for r in rows:
            before = daily.get(r[1], 0)
            after = before + r[2]
            daily[r[1]] = after
            r[4] = max(0, after - 480) - max(0, before - 480)
        weekly = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            before = weekly.get(wk, 0)
            reg = r[2] - r[4]
            after = before + reg
            weekly[wk] = after
            r[5] = max(0, after - 2400) - max(0, before - 2400)
        out = res[emp]
        ratelist = rates.get(emp, [])
        for _, wd, paid, night, dot, wot in rows:
            ot = dot + wot
            reg = paid - ot
            rate = None
            for eff, rt in ratelist:
                if eff <= wd:
                    rate = rt
            if rate is None and ratelist:
                rate = ratelist[0][1]
            if rate is None:
                rate = Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            out["shifts"] += 1
            out["paid_minutes"] += paid
            out["overtime_minutes"] += ot
            out["night_minutes"] += night
            out["gross"] += pay

    emps_out = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totg = 0
    for e in sorted(res):
        v = res[e]
        cents = round_cents(v["gross"])
        emps_out[e] = dict(shifts=v["shifts"], paid_minutes=v["paid_minutes"],
                           overtime_minutes=v["overtime_minutes"], night_minutes=v["night_minutes"],
                           gross="%d.%02d" % divmod(cents, 100))
        for k in tot:
            tot[k] += v[k]
        totg += cents
    tot["gross"] = "%d.%02d" % divmod(totg, 100)
    result = {"period": {"start": period["start"], "end": period["end"]},
              "employees": emps_out, "exceptions": exc, "totals": tot}
    with open(outfile, "w") as f:
        json.dump(result, f, indent=1)


if __name__ == "__main__":
    main()

